INSERT INTO `places` (`record_key`, `place_id`, `google_map_url`, `title`, `category`, `address`, `phone`, `website`, `latitude`, `longitude`, `data_json`, `updated_at`) VALUES ('3f1a5f94eb20f02922eb39a5bd260e0b010588033db4919fd1e697156495e0fe', 'ChIJ4foG-QOsNTERItMrsIb5jkM', 'https://www.google.com/maps/place/Nguy%E1%BB%85n+Kh%C6%B0%C6%A1ng+-+Gi%E1%BA%A3i+c%C6%A1+%C4%91au+vai+g%C3%A1y+l%C6%B0ng+h%C3%B4ng+chuy%C3%AAn+s%C3%A2u/data=!4m7!3m6!1s0x3135ac03f906fae1:0x438ef986b02bd322!8m2!3d21.003515!4d105.868905!16s%2Fg%2F11fzf96t17!19sChIJ4foG-QOsNTERItMrsIb5jkM?authuser=0&hl=vi&g_ep=EgoyMDI2MDkxNi4wIJJjKgBIAVAD&rclk=1', 'Nguyễn Khương - Giải cơ đau vai gáy lưng hông chuyên sâu', 'Người chữa bệnh bằng phương pháp nắn khớp xương', '24 Ng. 523 Minh Khai, Vĩnh Tuy, Hà Nội 100000, Việt Nam', 'Số điện thoại: +84 793 031 944', 'https://nguyenkhuong.com/', 21.0035150, 105.8689050, '{\"cid\": \"438ef986b02bd322\", \"link\": \"https://www.google.com/maps/place/Nguy%E1%BB%85n+Kh%C6%B0%C6%A1ng+-+Gi%E1%BA%A3i+c%C6%A1+%C4%91au+vai+g%C3%A1y+l%C6%B0ng+h%C3%B4ng+chuy%C3%AAn+s%C3%A2u/data=!4m7!3m6!1s0x3135ac03f906fae1:0x438ef986b02bd322!8m2!3d21.003515!4d105.868905!16s%2Fg%2F11fzf96t17!19sChIJ4foG-QOsNTERItMrsIb5jkM?authuser=0&hl=vi&g_ep=EgoyMDI2MDkxNi4wIJJjKgBIAVAD&rclk=1\", \"zone\": \"199\", \"phone\": \"Số điện thoại: +84 793 031 944\", \"title\": \"Nguyễn Khương - Giải cơ đau vai gáy lưng hông chuyên sâu\", \"images\": [\"https://lh3.googleusercontent.com/grass-cs/ACvplmM0_-TflsaesOLnuNWL5g23VEdx6M3l4twmC-1KquKeBBsyiB5ycOBiS1_Kn3jRvsKdi7AtBdj1wLiBk4AHUEUhI-EHxHs6ZocpMsFcXOhHTjUsXvJrrsAjJuTmwy-HZC_wuOOJWktE8vdO=w32-h32-p-k-no\", \"https://lh3.googleusercontent.com/grass-cs/ACvplmM0_-TflsaesOLnuNWL5g23VEdx6M3l4twmC-1KquKeBBsyiB5ycOBiS1_Kn3jRvsKdi7AtBdj1wLiBk4AHUEUhI-EHxHs6ZocpMsFcXOhHTjUsXvJrrsAjJuTmwy-HZC_wuOOJWktE8vdO=w408-h544-k-no\", \"https://lh3.googleusercontent.com/grass-cs/ACvplmORO08N3ACLLDYduleNgtnjO4YIi083focZgfChmGeLboZ8uhX7jeJr4GYJIYBBs0udSgl_sW0zJqoTBe5Xsq0iECpk0AO1FUbB3gt858jMIqiakeBaZb5aCCVXIUTCDKy5aRdD=w160-h120-k-no\", \"https://lh3.googleusercontent.com/a-/ALV-UjUhNFtbxavJqRiI5otCRki8PF0nBlL0Q6DDByknD1SnMbkgAj5sXw=w36-h36-p-rp-mo-ba12-br100\", \"https://lh3.googleusercontent.com/a/ACg8ocJlMxsM95gAqrOqpQ7EzfL821WJy39LHJj47TQC5sNRhOW05g=w36-h36-p-rp-mo-br100\", \"https://lh3.googleusercontent.com/a-/ALV-UjU4pVqLMjQG9qE0gndsH23Zi8534ha2ghPsOHO49qz1lETiLg0H=w36-h36-p-rp-mo-ba12-br100\"], \"status\": \"Đã đóng cửa · Mở cửa lúc 8:30 Thứ 3 \", \"address\": \"24 Ng. 523 Minh Khai, Vĩnh Tuy, Hà Nội 100000, Việt Nam\", \"data_id\": \"0x438ef986b02bd322\", \"details\": {\"json_ld\": [], \"detail_text\": \"Đăng nhập để khai thác tối đa Google Maps\\n\\nBài đánh giá và ảnh: Đọc và tìm kiếm mọi bài đánh giá và ảnh.\\n\\nĐịa điểm đã lưu. Theo dõi những địa điểm yêu thích bằng danh sách mà bạn có thể chia sẻ.\\n\\nThời gian di chuyển được cá nhân hoá. Nhận ngay thông tin về thời gian di chuyển đến những địa điểm bạn thường đến, chẳng hạn như nhà riêng và nơi làm việc.\\nLoại bỏ\\nĐăng nhập\\n\\n\\n\\nNhà hàng\\n\\nKhách sạn\\n\\nĐiểm tham quan\\n\\nPhương tiện công cộng\\n\\nBãi đỗ xe\\n\\nHiệu thuốc\\n\\nATM\\n\\n\\n\\nĐã lưu\\n\\nGần đây\\nNguyễn Khương - Giải cơ đau vai gáy lưng hông chuyên sâu\\n\\nTải ứng dụng\\n\\nXem ảnh\\nNguyễn Khương - Giải cơ đau vai gáy lưng hông chuyên sâu\\n5,0\\n(532)\\nNgười chữa bệnh bằng phương pháp nắn khớp xương·\\nTổng quan\\nBài đánh giá\\nGiới thiệu\\n\\nĐường đi\\n\\nLưu\\n\\nGần đó\\n\\nGửi tới điện thoại\\n\\nChia sẻ\\n \\n\\n24 Ng. 523 Minh Khai, Vĩnh Tuy, Hà Nội 100000, Việt Nam\\n\\n\\nĐã đóng cửa · Mở cửa lúc 8:30 Thứ 3\\n\\n\\nnguyenkhuong.com\\n\\n\\n\\n+84 793 031 944\\n\\n\\n\\n2V39+CH Vĩnh Tuy, Hà Nội, Việt Nam\\n\\n\\n \\n\\nĐề xuất chỉnh sửa\\n \\nTừ chủ sở hữu\\nBuổi đầu tiên ở đây là buổi KIỂM TRA, không tính tiền. Nhiều khách hỏi tôi qua điện thoại \\\"tôi bị thế này có chữa được không\\\". Tôi không trả lời được câu đó qua điện thoại — nghề này đọc bằng tay, không đọc bằng tai. Hai người mô tả giống hệt nhau \\\"mỏi gáy, tê tay\\\", nhưng khi sờ vào thì một người căng cơ thang, người kia lại là cơ bậc thang trước chèn ép. Hai tình trạng đó xử lý khác nhau hoàn toàn. Nên buổi đầu tôi chạm tay kiểm tra trực tiếp, nói rõ tình trạng cơ của bạn, rồi bạn mới quyết định có làm hay không. Nếu sờ xong tôi thấy mình không giúp được, tôi nói thẳng ngay lúc đó. 24 ngõ 523 Minh Khai, Vĩnh Tuy · T2–T7 8:30–20:00 · CN 8:30–16:00\\n13 thg 8, 2026\\n \\nẢnh\\n\\n35 ảnh\\n \\n\\nThêm ảnh và video\\n \\nTóm tắt bài đánh giá\\n\\n5\\t\\n\\n4\\t\\n\\n3\\t\\n\\n2\\t\\n\\n1\\t\\n5,0\\n532 bài viết\\n \\n\\nViết bài đánh giá\\n \\nTất cả các bài đánh giá\\n\\nLinh Đỗ\\nLocal Guide · 19 bài đánh giá · 13 ảnh\\n\\n\\n\\n\\n\\n\\nmột tháng trước\\nĐịa chỉ giải cơ - trị liệu chắc tốt nhất Hà Nội. Trị liệu các vấn đề về nhiễm hàn và bó cơ rất tận gốc. Mọi người đến làm thì nên xác định làm tầm 2 buổi trở lên thì sẽ thấy hiệu quả rõ rệt hơn. Đã gặp rất nhiều ca sĩ, diễn viên, vđv đến đây để trị liệu\\n\\nThích\\n\\nChia sẻ\\nThông tin phản hồi từ chủ sở hữu một tháng trước\\ncảm ơn em \\n \\n \\nhang lammo\\n3 bài đánh giá · 3 ảnh\\n\\n\\n\\n\\n\\n\\n5 tháng trước\\nTrước khi đến đây tôi mỏi cơ, không quay cổ được, mỏi cơ cổ vai gáy, trị hai ngày tôi thấy đỡ hẳn, cơ thể đỡ đau nhức mệt mỏi hơn nhiều!\\n\\nThích\\n\\nChia sẻ\\nThông tin phản hồi từ chủ sở hữu 3 tháng trước\\nCảm ơn\\nBản dịch của Google ・ Xem bản gốc (Tiếng Anh)\\n \\n \\nphương Tô Mai\\nLocal Guide · 7 bài đánh giá · 16 ảnh\\n\\n\\n\\n\\n\\n\\n5 tháng trước\\n“Mình đã từng điều trị vai gáy ở rất nhiều nơi nhưng tình trạng vẫn không cải thiện. Cho đến khi gặp được bạn này, mình thực sự cảm thấy như trút bỏ được gánh nặng lâu năm. … Xem thêm\\n\\nThích\\n\\nChia sẻ\\nThông tin phản hồi từ chủ sở hữu 3 tháng trước\\nCảm ơn\\nBản dịch của Google ・ Xem bản gốc (Tiếng Anh)\\n \\nBài đánh giá khác (529)\\n \\nThông tin về dữ liệu này\\n\\nBạn