INSERT INTO `places` (`record_key`, `place_id`, `google_map_url`, `title`, `category`, `address`, `phone`, `website`, `latitude`, `longitude`, `data_json`, `updated_at`) VALUES ('656a26f4c67d5c718b8950bfb9339aff99b432b6390e0c9759e50257e4c8c46d', 'ChIJBUZzJRurNTERtE59nSWB1L0', 'https://www.google.com/maps/place/Oriental+Medicine+Clinic/data=!4m7!3m6!1s0x3135ab1b25734605:0xbdd481259d7d4eb4!8m2!3d21.0182741!4d105.8505454!16s%2Fg%2F11w4rjxfs0!19sChIJBUZzJRurNTERtE59nSWB1L0?authuser=0&hl=vi&g_ep=EgoyMDI2MDkxNi4wIJJjKgBIAVAD&rclk=1', 'Oriental Medicine Clinic', 'Phòng mạch y tế', '5 P. Triệu Việt Vương, Hai Bà Trưng, Hà Nội, Việt Nam', 'Số điện thoại: +84 24 7106 1199', 'https://www.saophuongdong.top/', 21.0182741, 105.8505454, '{\"cid\": \"bdd481259d7d4eb4\", \"link\": \"https://www.google.com/maps/place/Oriental+Medicine+Clinic/data=!4m7!3m6!1s0x3135ab1b25734605:0xbdd481259d7d4eb4!8m2!3d21.0182741!4d105.8505454!16s%2Fg%2F11w4rjxfs0!19sChIJBUZzJRurNTERtE59nSWB1L0?authuser=0&hl=vi&g_ep=EgoyMDI2MDkxNi4wIJJjKgBIAVAD&rclk=1\", \"zone\": \"199\", \"phone\": \"Số điện thoại: +84 24 7106 1199\", \"title\": \"Oriental Medicine Clinic\", \"images\": [\"https://lh3.googleusercontent.com/grass-cs/ACvplmPo1BKgp75NBh9TeUHl3eZsGswOWlJHC2B7QbWsUQKuI-dcCcoJknkwEZjLmCCc83eyLgADfr6ku2r6P6edh7WyHQTC3RTZaeLplmhxaT-SZ-tpoXSkEbqUpwViws5hwQspK0bEohp8vZdy=w32-h32-p-k-no\", \"https://lh3.googleusercontent.com/grass-cs/ACvplmPo1BKgp75NBh9TeUHl3eZsGswOWlJHC2B7QbWsUQKuI-dcCcoJknkwEZjLmCCc83eyLgADfr6ku2r6P6edh7WyHQTC3RTZaeLplmhxaT-SZ-tpoXSkEbqUpwViws5hwQspK0bEohp8vZdy=w408-h408-k-no\", \"https://lh3.googleusercontent.com/grass-cs/ACvplmOF_Mh7KlYqsN205M4AsPCEb6EofuTG59apvPaay7nGGcumbSZQWZ6sH_teqFfrNv2uCfHDg4h27xOPmzCCEoZNp69itGdWOXbx_1xzVtY128TdGzPONygNoIlAQ7TV-WOoCZhpniGP_lUF=w160-h120-k-no\", \"https://lh3.googleusercontent.com/a-/ALV-UjVIbOkjfcPOWLXR074xhaLsntLCUpKXNOl8B4I2cu6LO4YBXmZcig=w36-h36-p-rp-mo-ba12-br100\"], \"status\": \"Đã đóng cửa · Mở cửa lúc 9:00 Thứ 3 \", \"address\": \"5 P. Triệu Việt Vương, Hai Bà Trưng, Hà Nội, Việt Nam\", \"data_id\": \"0xbdd481259d7d4eb4\", \"details\": {\"json_ld\": [], \"detail_text\": \"Đăng nhập để khai thác tối đa Google Maps\\n\\nBài đánh giá và ảnh: Đọc và tìm kiếm mọi bài đánh giá và ảnh.\\n\\nĐịa điểm đã lưu. Theo dõi những địa điểm yêu thích bằng danh sách mà bạn có thể chia sẻ.\\n\\nThời gian di chuyển được cá nhân hoá. Nhận ngay thông tin về thời gian di chuyển đến những địa điểm bạn thường đến, chẳng hạn như nhà riêng và nơi làm việc.\\nLoại bỏ\\nĐăng nhập\\n\\n\\n\\nNhà hàng\\n\\nKhách sạn\\n\\nĐiểm tham quan\\n\\nPhương tiện công cộng\\n\\nBãi đỗ xe\\n\\nHiệu thuốc\\n\\nATM\\n\\n\\n\\nĐã lưu\\n\\nGần đây\\nOriental Medicine Clinic\\n\\nTải ứng dụng\\n\\nXem ảnh\\nOriental Medicine Clinic\\n5,0\\n(1)\\nPhòng mạch y tế\\nTổng quan\\nBài đánh giá\\n\\nĐường đi\\n\\nLưu\\n\\nGần đó\\n\\nGửi tới điện thoại\\n\\nChia sẻ\\n \\n\\n5 P. Triệu Việt Vương, Hai Bà Trưng, Hà Nội, Việt Nam\\n\\n\\nĐã đóng cửa · Mở cửa lúc 9:00 Thứ 3\\n\\n\\nsaophuongdong.top\\n\\n\\n\\n+84 24 7106 1199\\n\\n\\n\\n2V92+86 Hai Bà Trưng, Hà Nội, Việt Nam\\n\\n\\n \\n\\nĐề xuất chỉnh sửa\\n \\nẢnh\\n\\n5 ảnh\\n \\n\\nThêm ảnh và video\\n \\nTóm tắt bài đánh giá\\n\\n5\\t\\n\\n4\\t\\n\\n3\\t\\n\\n2\\t\\n\\n1\\t\\n5,0\\n1 bài đánh giá\\n \\n\\nViết bài đánh giá\\n \\nTất cả các bài đánh giá\\n\\nMichaela Hrabankova\\nLocal Guide · 60 bài đánh giá · 64 ảnh\\n\\n\\n\\n\\n\\n\\nmột năm trước\\nĐối với tôi, đây là một trong những trải nghiệm châm cứu tuyệt vời nhất trong đời. Bác sĩ rất chuyên nghiệp và có phương pháp tuyệt vời. Ông ấy đã hỏi tôi nhiều câu hỏi và giải thích cho tôi rất nhiều điều về tương lai của tôi.\\nBản dịch của Google ・ Xem bản gốc (Tiếng Anh)\\n\\nThích\\n\\nChia sẻ\\nThông tin phản hồi từ chủ sở hữu một năm trước\\nCảm ơn chị Michaela Hrbankova rất nhiều vì đã chia sẻ trải nghiệm tuyệt vời tại phòng khám của chúng tôi. Chúng tôi thực sự trân trọng sự tin tưởng và những lời tốt đẹp của chị. … Xem thêm\\nBản dịch của Google ・ Xem bản gốc (Tiếng Anh)\\n \\nThông tin về dữ liệu này\\n\\nBạn đang xem Google Maps ở chế độ bị hạn chế. Xem thêm\\n\\nĐăng nhập\\n\\n\\n\\n\\n Lớp\\nDữ liệu bản đồ ©2026 Toàn cầuĐiều khoảnQuyền riêng tưGửi ý kiến phản hồi về sản phẩm\\n\\t100 mét \"}, \"website\": \"https://www.saophuongdong.top/\", \"category\": \"Phòng mạch y tế\", \"latitude\": 21.0182741, \"place_id\": \"ChIJBUZzJRurNTERtE59nSWB1L0\", \"raw_text\": \"Oriental Medicine Clinic\", \"longitude\": 105.8505454, \"plus_code\": \"2V92+86 Hai Bà Trưng, Hà Nội, Việt Nam\", \"open_hours\": {\"Thứ Hai\": \"09:00 đến 18:00\"}, \"review_count\": 1, \"source_query\": \"acupuncture\", \"review_rating\": 5, \"google_map_url\": \"https://www.google.com/maps/place/Oriental+Medicine+Clinic/data=!4m7!3m6!1s0x3135ab1b25734605:0xbdd481259d7d4eb4!8m2!3d21.0182741!4d105.8505454!16s%2Fg%2F11w4rjxfs0!19sChIJBUZzJRurNTERtE59nSWB1L0?authuser=0&hl=vi&g_ep=EgoyMDI2MDkxNi4wIJJjKgBIAVAD&rclk=1\", \"raw_detail_text\": \"Đăng nhập để khai thác tối đa Google Maps\\n\\nBài đánh giá và ảnh: Đọc và tìm kiếm mọi bài đánh giá và ảnh.\\n\\nĐịa điểm đã lưu. Theo dõi những địa điểm yêu thích bằng danh sách mà bạn có thể chia sẻ.\\n\\nThời gian di chuyển được cá nhân hoá. Nhận ngay thông tin về thời gian di chuyển đến những địa điểm bạn thường đến, chẳng hạn như nhà riêng và nơi làm việc.\\nLoại bỏ\\nĐăng nhập\\n\\n\\n\\nNhà hàng\\n\\nKhách sạn\\n\\nĐiểm tham quan\\n\\nPhương tiện công cộng\\n\\nBãi đỗ xe\\n\\nHiệu thuốc\\n\\nATM\\n\\n\\n\\nĐã lưu\\n\\nGần đây\\nOriental Medicine Clinic\\n\\nTải ứng dụng\\n\\nXem ảnh\\nOriental Medicine Clinic\\n5,0\\n(1)\\nPhòng mạch y tế\\nTổng quan\\nBài đánh giá\\n\\nĐường đi\\n\\nLưu\\n\\nGần đó\\n\\nGửi tới điện thoại\\n\\nChia sẻ\\n \\n\\n5 P. Triệu Việt Vương, Hai Bà Trưng, Hà Nội, Việt Nam\\n\\n\\nĐã đóng cửa · Mở cửa lúc 9:00 Thứ 3\\n\\n\\nsaophuongdong.top\\n\\n\\n\\n+84 24 7106 1199\\n\\n\\n\\