INSERT INTO `places` (`record_key`, `place_id`, `google_map_url`, `title`, `category`, `address`, `phone`, `website`, `latitude`, `longitude`, `data_json`, `updated_at`) VALUES ('869c607613361ac28642c5116f23e16020c0bd60f70e2fe67166612d7ec75765', 'ChIJ6SQw-vurNTEReUDxrsQvIrY', 'https://www.google.com/maps/place/Thi%C3%AAn+An+Y+Qu%C3%A1n+-+Xoa+B%C3%B3p+B%E1%BA%A5m+Huy%E1%BB%87t+%26+Tr%E1%BB%8B+Li%E1%BB%87u+C%E1%BB%95+Vai+G%C3%A1y+%28CS2+C%E1%BA%A7u+Gi%E1%BA%A5y%29/data=!4m7!3m6!1s0x3135abfbfa3024e9:0xb6222fc4aef14079!8m2!3d21.0417453!4d105.8038218!16s%2Fg%2F11ysjncybn!19sChIJ6SQw-vurNTEReUDxrsQvIrY?authuser=0&hl=vi&g_ep=EgoyMDI2MDkxNi4wIJJjKgBIAVAD&rclk=1', 'Thiên An Y Quán - Xoa Bóp Bấm Huyệt & Trị Liệu Cổ Vai Gáy (CS2 Cầu Giấy)', 'Phòng khám vật lý trị liệu', 'ngách 61/17 Ngõ 61 Phùng Chí Kiên, Nghĩa Đô, Hà Nội 11307, Việt Nam', 'Số điện thoại: +84 798 816 866', '', 21.0417453, 105.8038218, '{\"cid\": \"b6222fc4aef14079\", \"link\": \"https://www.google.com/maps/place/Thi%C3%AAn+An+Y+Qu%C3%A1n+-+Xoa+B%C3%B3p+B%E1%BA%A5m+Huy%E1%BB%87t+%26+Tr%E1%BB%8B+Li%E1%BB%87u+C%E1%BB%95+Vai+G%C3%A1y+%28CS2+C%E1%BA%A7u+Gi%E1%BA%A5y%29/data=!4m7!3m6!1s0x3135abfbfa3024e9:0xb6222fc4aef14079!8m2!3d21.0417453!4d105.8038218!16s%2Fg%2F11ysjncybn!19sChIJ6SQw-vurNTEReUDxrsQvIrY?authuser=0&hl=vi&g_ep=EgoyMDI2MDkxNi4wIJJjKgBIAVAD&rclk=1\", \"zone\": \"001\", \"phone\": \"Số điện thoại: +84 798 816 866\", \"title\": \"Thiên An Y Quán - Xoa Bóp Bấm Huyệt & Trị Liệu Cổ Vai Gáy (CS2 Cầu Giấy)\", \"images\": [\"https://lh3.googleusercontent.com/gps-cs-s/AHRPTWlnwMeUM2D4akkOhnWrfDSjE8-lbT_3XwATMvWP2WWpuMtpXHrMYsoCVK-l-Pl4LQ_Z20J90_0Gd-1jnk2Ugiw_9vrGWmRuDay06jApsSyv7-Y6HCuHnGhJkh_BbBFB1IAyJgu7hyUPgoaO=w32-h32-p-k-no\", \"https://lh3.googleusercontent.com/gps-cs-s/AHRPTWlnwMeUM2D4akkOhnWrfDSjE8-lbT_3XwATMvWP2WWpuMtpXHrMYsoCVK-l-Pl4LQ_Z20J90_0Gd-1jnk2Ugiw_9vrGWmRuDay06jApsSyv7-Y6HCuHnGhJkh_BbBFB1IAyJgu7hyUPgoaO=w408-h321-k-no\", \"https://lh3.googleusercontent.com/gps-cs-s/AHRPTWnunauH0B8fIIhr44Sx0OSR0QnGEY-zTaFRt4QEqldzCCUiCYX8z506_QFQC1jGtjTV_30teQE_PchmsIb5ctE_kUTo7g88tTRhX_8R2q9mX2MG46SzCR-8AwsgUpkIkpAqKfHoSH_fEV8x=w140-h186-k-no\", \"https://lh3.googleusercontent.com/a/ACg8ocKO4NIUngGZBSAWEKfBGHYPvlMDecDD6jNX-xtcvSe6zhGjdLCa=w36-h36-p-rp-mo-ba12-br100\", \"https://lh3.googleusercontent.com/a-/ALV-UjW_xmXebvyRDL6zn5MYjgTNrSt2PCC67VelEiHXTP6ZtDg9dZEz=w36-h36-p-rp-mo-br100\", \"https://lh3.googleusercontent.com/a-/ALV-UjVfu07lUKaM94fSGZkPmaAxbEDNOjv6poTppNcEtOmnQG2SCDfx=w36-h36-p-rp-mo-br100\"], \"status\": \"Đã đóng cửa · Mở cửa lúc 8:00 \", \"address\": \"ngách 61/17 Ngõ 61 Phùng Chí Kiên, Nghĩa Đô, Hà Nội 11307, Việt Nam\", \"data_id\": \"0xb6222fc4aef14079\", \"details\": {\"json_ld\": [], \"detail_text\": \"Đăng nhập để khai thác tối đa Google Maps\\n\\nBài đánh giá và ảnh: Đọc và tìm kiếm mọi bài đánh giá và ảnh.\\n\\nĐịa điểm đã lưu. Theo dõi những địa điểm yêu thích bằng danh sách mà bạn có thể chia sẻ.\\n\\nThời gian di chuyển được cá nhân hoá. Nhận ngay thông tin về thời gian di chuyển đến những địa điểm bạn thường đến, chẳng hạn như nhà riêng và nơi làm việc.\\nLoại bỏ\\nĐăng nhập\\n\\n\\n\\nNhà hàng\\n\\nKhách sạn\\n\\nĐiểm tham quan\\n\\nPhương tiện công cộng\\n\\nBãi đỗ xe\\n\\nHiệu thuốc\\n\\nATM\\n\\n\\n\\nĐã lưu\\n\\nGần đây\\nThiên An Y Quán - Xoa Bóp Bấm Huyệt & Trị Liệu Cổ Vai Gáy (CS2 Cầu Giấy)\\n\\nTải ứng dụng\\n\\nXem ảnh\\nThiên An Y Quán - Xoa Bóp Bấm Huyệt & Trị Liệu Cổ Vai Gáy (CS2 Cầu Giấy)\\n5,0\\n(36)\\nPhòng khám vật lý trị liệu\\nTổng quan\\nBài đánh giá\\n\\nĐường đi\\n\\nLưu\\n\\nGần đó\\n\\nGửi tới điện thoại\\n\\nChia sẻ\\n \\n\\nngách 61/17 Ngõ 61 Phùng Chí Kiên, Nghĩa Đô, Hà Nội 11307, Việt Nam\\n\\n\\nĐã đóng cửa · Mở cửa lúc 8:00\\n\\n\\n+84 798 816 866\\n\\n\\n\\n2RR3+MG Nghĩa Đô, Hà Nội, Việt Nam\\n\\n\\n \\n\\nĐề xuất chỉnh sửa\\n \\nThêm thông tin bị thiếu\\n\\n\\nThêm trang web\\n \\nTừ chủ sở hữu\\nChia sẻ phương pháp dưỡng sinh đơn giản, hiệu quả: Tại Thiên An, ngoài việc chăm sóc khách hàng, bệnh nhân thì các bác sĩ cũng cần phải có những phương pháp dưỡng sinh để nâng cao chính khí, phục hồi thể trạng sau khi làm việc vất vả. Qua nhiều năm ứng dụng thực tế, đội ngũ thấy phương pháp dưỡng sinh dưới đây đơn giản, dễ thực hiện, phù hợp với đa số mọi người lên muốn phổ biến rộng rãi. Cô, bác, anh, chị, em nhấn vào theo giõi fanpage để tìm hiểu về phương pháp và liên hệ Thiên An khi cần chăm sóc sức khỏe nhé ạ! https://www.facebook.com/share/v/1M2EWyPgFU/\\n19 giờ trước\\n \\nẢnh\\n\\nHơn 44 ảnh\\n \\n\\nThêm ảnh và video\\n \\nTóm tắt bài đánh giá\\n\\n5\\t\\n\\n4\\t\\n\\n3\\t\\n\\n2\\t\\n\\n1\\t\\n5,0\\n36 bài viết\\n \\n\\nViết bài đánh giá\\n \\nTất cả các bài đánh giá\\n\\nĐức Anh Phạm\\nLocal Guide · 132 bài đánh giá · 86 ảnh\\n\\n\\n\\n\\n\\n\\n4 tháng trước\\nBác sĩ chuyên môn cao, thao tác chuẩn không màu mè, có giác hơi, bấm huyệt, châm cứu, dùng thuốc\\n0:25\\n+2 mục khác\\n\\nThích\\n\\nChia sẻ\\nThông tin phản hồi từ chủ sở hữu 4 tháng trước\\nCảm ơn anh đã tin tưởng bên em ạ. rất mong mỗi lần anh đến đều đạt được hiệu quả đtri tốt nhất ạ. \\n \\n \\nLy Đỗ\\n1 bài đánh giá · 1 ảnh\\n\\n\\n\\n\\n\\n\\nmột tuần trước\\nMỚI\\nKhông gian phòng khám thoáng đãng, sạch sẽ, các bạn bác sĩ tư vấn tận tâm và nhiệt tình\\n\\nThích\\n\\nChia sẻ\\n \\n \\nQuynh Vu\\n5 bài đánh giá · 6 ảnh\\n\\n\\n\\n\\n\\n\\n8 tháng trước\\nMình đến phòng khám đã nhiều lần. Phòng khám sạch sẽ, có chuyên môn, đội ngũ có chuyên môn. Sản phẩm uy tín, hàng thật, chất lượng tốt nhưng sẽ hơi cao một chút. Phù hợp cho ai muốn chăm sóc sức khoẻ bền vững, lành tính, lâu dài. Nhiều năm … Xem thêm\\n\\nThích\\n\\nChia sẻ\\nThông tin phản hồi từ chủ sở hữu 4 tháng trước\\nrất mong mỗi lần chị đến đều đạt được hiệu quả đtri tốt nhất ạ. \\n \\nBài đánh giá khác (33)\\n \\nThông tin về dữ liệu này\\n\\nBạn đang xem Google Maps ở chế độ bị hạn chế. Xem thêm\\n\\nĐăng nhập\\n\\n\\n\\n\\n Lớp\\nDữ liệu bản đồ ©2026 Toàn cầuĐiều khoảnQ