INSERT INTO `places` (`record_key`, `place_id`, `google_map_url`, `title`, `category`, `address`, `phone`, `website`, `latitude`, `longitude`, `data_json`, `updated_at`) VALUES ('b06998d90e5f75ac0ec717c39397ccdcf0a08ab9a8b2ae4bc6cdb5a7fb6c88e4', 'ChIJdwm45papNTER6BWGJUyE9oA', 'https://www.google.com/maps/place/%C4%90%C3%B4ng+Y+%C4%90%C3%A0o+Gia/data=!4m7!3m6!1s0x3135a996e6b80977:0x80f6844c258615e8!8m2!3d21.008189!4d105.9519901!16s%2Fg%2F11m62062q6!19sChIJdwm45papNTER6BWGJUyE9oA?authuser=0&hl=vi&g_ep=EgoyMDI2MDkyMS4wIJJjKgBIAVAD&rclk=1', 'Đông Y Đào Gia', 'Vật lý trị liệu', '82 Ngõ 6 Lý Thánh Tông, Kiên Thành, Gia Lâm, Hà Nội, Việt Nam', 'Số điện thoại: +84 347 290 883', '', 21.0081890, 105.9519901, '{\"cid\": \"80f6844c258615e8\", \"link\": \"https://www.google.com/maps/place/%C4%90%C3%B4ng+Y+%C4%90%C3%A0o+Gia/data=!4m7!3m6!1s0x3135a996e6b80977:0x80f6844c258615e8!8m2!3d21.008189!4d105.9519901!16s%2Fg%2F11m62062q6!19sChIJdwm45papNTER6BWGJUyE9oA?authuser=0&hl=vi&g_ep=EgoyMDI2MDkyMS4wIJJjKgBIAVAD&rclk=1\", \"zone\": \"164\", \"phone\": \"Số điện thoại: +84 347 290 883\", \"title\": \"Đông Y Đào Gia\", \"images\": [\"https://lh3.googleusercontent.com/gps-cs-s/AHRPTWmDt1Mh8SSdXrrr5q4VzCrDgjHvxMJ4QjMQF4zJxIMIwy67g9KaIK0WQHMVdqDBAqu9zf80Zr1uO2mx0iVWYSAeYXxbA0z8wibvCNbycZkHIkl-P_rh0P2o4fc9WCqNmfvAj7sO3faLqgYB=w32-h32-p-k-no\", \"https://lh3.googleusercontent.com/a-/ALV-UjWh9FfVzxrljcQzsLNPRGeZomBDYvppZf916BKGNIvqSd0fA9g=w36-h36-p-rp-mo-br100\", \"https://lh3.googleusercontent.com/a-/ALV-UjU7KUTO3wjGXpu_80xvxZy3Mb29jbFX1SwA17WwhTpdlDbubYg=w36-h36-p-rp-mo-br100\", \"https://lh3.googleusercontent.com/a-/ALV-UjXCCANkf9xKJ-H-GUZI8Hr-gFgkbb37ba2s5Mh6i7AirR6eaU8D=w36-h36-p-rp-mo-br100\"], \"status\": \"Mở cả ngày \", \"address\": \"82 Ngõ 6 Lý Thánh Tông, Kiên Thành, Gia Lâm, Hà Nội, Việt Nam\", \"data_id\": \"0x80f6844c258615e8\", \"details\": {\"json_ld\": [], \"detail_text\": \"Đăng nhập để khai thác tối đa Google Maps\\n\\nBài đánh giá và ảnh: Đọc và tìm kiếm mọi bài đánh giá và ảnh.\\n\\nĐịa điểm đã lưu. Theo dõi những địa điểm yêu thích bằng danh sách mà bạn có thể chia sẻ.\\n\\nThời gian di chuyển được cá nhân hoá. Nhận ngay thông tin về thời gian di chuyển đến những địa điểm bạn thường đến, chẳng hạn như nhà riêng và nơi làm việc.\\nLoại bỏ\\nĐăng nhập\\n\\n\\n\\nNhà hàng\\n\\nKhách sạn\\n\\nĐiểm tham quan\\n\\nPhương tiện công cộng\\n\\nBãi đỗ xe\\n\\nHiệu thuốc\\n\\nATM\\n\\n\\n\\nĐã lưu\\n\\nGần đây\\nĐông Y Đào Gia\\n\\nTải ứng dụng\\n\\nXem ảnh\\nĐông Y Đào Gia\\n5,0\\n(20)\\nVật lý trị liệu\\nTổng quan\\nBài đánh giá\\n\\nĐường đi\\n\\nLưu\\n\\nGần đó\\n\\nGửi tới điện thoại\\n\\nChia sẻ\\n \\n\\n82 Ngõ 6 Lý Thánh Tông, Kiên Thành, Gia Lâm, Hà Nội, Việt Nam\\n\\n\\nMở cả ngày\\n\\n\\n+84 347 290 883\\n\\n\\n\\n2X52+7Q Gia Lâm, Hà Nội, Việt Nam\\n\\n\\n \\n\\nĐề xuất chỉnh sửa\\n \\nThêm thông tin bị thiếu\\n\\n\\nThêm trang web\\n \\nẢnh\\n\\n5 ảnh\\n \\n\\nThêm ảnh và video\\n \\nTóm tắt bài đánh giá\\n\\n5\\t\\n\\n4\\t\\n\\n3\\t\\n\\n2\\t\\n\\n1\\t\\n5,0\\n20 bài viết\\n \\n\\nViết bài đánh giá\\n \\nTất cả các bài đánh giá\\n\\nLoc Pham\\n1 bài đánh giá\\n\\n\\n\\n\\n\\n\\nmột năm trước\\nTôi điều trị vật lý trị liệu ở đây thấy hiệu quả rõ rệt lắm. Bác sĩ giàu kinh nghiệm và có tâm với người bệnh.\\n\\nThích\\n\\nChia sẻ\\n \\n \\nÁnh Đào\\n4 bài đánh giá · 1 ảnh\\n\\n\\n\\n\\n\\n\\nmột năm trước\\nMình bị đau cổ vai gáy không quay đầu được, đến bs Dung thăm khám và châm cứu xoa bóp cho 3b là thấy đỡ hẳn. 👍 …\\n\\nThích\\n\\nChia sẻ\\n \\n \\nOhO OhO\\n2 bài đánh giá\\n\\n\\n\\n\\n\\n\\nmột năm trước\\nBác sĩ nhiệt tình, giải thích cặn kẽ tình trạng bệnh và hướng dẫn cách dùng thuốc rất chi tiết.\\n\\nThích\\n\\nChia sẻ\\n \\nBài đánh giá khác (17)\\n \\nThông tin về dữ liệu này\\n\\nBạn đang xem Google Maps ở chế độ bị hạn chế. Xem thêm\\n\\nĐăng nhập\\n\\n\\n\\n\\n Lớp\\nDữ liệu bản đồ ©2026 Toàn cầuĐiều khoảnQuyền riêng tưGửi ý kiến phản hồi về sản phẩm\\n\\t100 mét \"}, \"category\": \"Vật lý trị liệu\", \"latitude\": 21.008189, \"place_id\": \"ChIJdwm45papNTER6BWGJUyE9oA\", \"raw_text\": \"Đông Y Đào Gia\", \"longitude\": 105.9519901, \"plus_code\": \"2X52+7Q Gia Lâm, Hà Nội, Việt Nam\", \"open_hours\": {\"Thứ Năm\": \"Mở cửa cả ngày, Sao chép giờ mở cửa\"}, \"review_count\": 20, \"source_query\": \"acupuncture\", \"review_rating\": 5, \"google_map_url\": \"https://www.google.com/maps/place/%C4%90%C3%B4ng+Y+%C4%90%C3%A0o+Gia/data=!4m7!3m6!1s0x3135a996e6b80977:0x80f6844c258615e8!8m2!3d21.008189!4d105.9519901!16s%2Fg%2F11m62062q6!19sChIJdwm45papNTER6BWGJUyE9oA?authuser=0&hl=vi&g_ep=EgoyMDI2MDkyMS4wIJJjKgBIAVAD&rclk=1\", \"raw_detail_text\": \"Đăng nhập để khai thác tối đa Google Maps\\n\\nBài đánh giá và ảnh: Đọc và tìm kiếm mọi bài đánh giá và ảnh.\\n\\nĐịa điểm đã lưu. Theo dõi những địa điểm yêu thích bằng danh sách mà bạn có thể chia sẻ.\\n\\nThời gian di chuyển được cá nhân hoá. Nhận ngay thông tin về thời gian di chuyển đến những địa điểm bạn thường đến, chẳng hạn như nhà riêng và nơi làm việc.\\nLoại bỏ\\nĐăng nhập\\n\\n\\n\\nNhà hàng\\n\\nKhách sạn\\n\\nĐiểm tham quan\\n\\nPhương tiện công cộng\\n\\nBãi đỗ xe\\n\\nHiệu thuốc\\n\\nATM\\n\\n\\n\\nĐã lưu\\n\\nGần đây\\nĐông Y Đào Gia\\n\\nTải ứng dụng\\n\\nXem ảnh\\nĐông Y Đào Gia\\n5,0\\n(20)\\nVật lý trị liệu\\nTổng quan\\nBài đánh giá\\n\\nĐường đi\\n\\nLưu\\n\\nGần đó\\n\\nGửi tới điện thoại\\n\\nChia sẻ\\n \\n\\n82 Ngõ 6 Lý Thánh Tông, Kiên Thành, Gia Lâm, Hà Nội, Việt Nam\\n\\n\\nMở cả ngày\\n\\n\\n+84 347 290 883\\n\\n\\n\\n2X52+7Q Gia Lâm, Hà Nội, Việt Nam\\n\\n\\n \\n\\nĐề xuất chỉnh sửa\\n \\nThêm thông tin bị thiếu\\n\\n\\nThêm trang web\\n \\nẢnh\\n\\n5 ảnh\\n \\n\\nThêm ảnh và video\\n \\nTóm tắt bài đánh giá\\n\\n5\\t\\n\\n4\\t\\n\\n3\\t\\n\\n2\\t\\n\\n1\\t\\n5,0\\n20 bài viết\\n \\n\\nViết bài đánh giá\\n \\nTất cả các bài đánh giá\\n\\nLoc Pham\\n1 bài đánh giá\\n\\n\\n\\n\\n\\n\\nmột nă